//go:build !purego

package aes

// AES block functions for the T-Head C906 (aes_c906_riscv64.s, generated by
// gen_aes_c906.py). NanoKVM OS runs only on this CPU, which has XTheadBb and
// XTheadMemIdx: there is no selection.
//
// The assembly takes the round keys as little-endian words (the generic code
// keeps them big-endian) and four tables of 1 KiB per direction, table j
// being table 0 rotated left by 8 j bits; the 256 bytes after the decryption
// tables are the inverse S-box.

//go:noescape
func encryptBlockC906(rk *uint32, nrounds int, dst, src *byte, tables *uint32)

//go:noescape
func decryptBlockC906(rk *uint32, nrounds int, dst, src *byte, tables *uint32)

//go:noescape
func ctr32BlocksC906(rk *uint32, nrounds int, dst, src *byte, nblocks int, counter *[16]byte, tables *uint32)

var (
	c906Enc [4 * 256]uint32
	c906Dec [4*256 + 256/4]uint32
)

// c906Mul multiplies in GF(2⁸) modulo poly.
func c906Mul(a, b uint32) uint32 {
	var r uint32
	for ; b != 0; b >>= 1 {
		if b&1 != 0 {
			r ^= a
		}
		a <<= 1
		if a&0x100 != 0 {
			a ^= poly
		}
	}
	return r
}

func init() {
	for i := 0; i < 256; i++ {
		s := uint32(sbox0[i])
		e := c906Mul(s, 2) | s<<8 | s<<16 | c906Mul(s, 3)<<24
		v := uint32(sbox1[i])
		d := c906Mul(v, 14) | c906Mul(v, 9)<<8 | c906Mul(v, 13)<<16 | c906Mul(v, 11)<<24
		for j := 0; j < 4; j++ {
			c906Enc[256*j+i] = e<<(8*j) | e>>(32-8*j)
			c906Dec[256*j+i] = d<<(8*j) | d>>(32-8*j)
		}
		c906Dec[4*256+i/4] |= v << (8 * (i % 4))
	}
}

type block struct {
	blockExpanded
	// The round keys of blockExpanded with the bytes of each word reversed.
	encLE, decLE [60]uint32
}

func c906Reverse(w uint32) uint32 {
	return w<<24 | w&0xff00<<8 | w>>8&0xff00 | w>>24
}

func newBlock(c *Block, key []byte) *Block {
	newBlockExpanded(&c.blockExpanded, key)
	for i := 0; i < c.roundKeysSize(); i++ {
		c.encLE[i] = c906Reverse(c.enc[i])
		c.decLE[i] = c906Reverse(c.dec[i])
	}
	return c
}

func encryptBlock(c *Block, dst, src []byte) {
	encryptBlockC906(&c.encLE[0], c.rounds, &dst[0], &src[0], &c906Enc[0])
}

func decryptBlock(c *Block, dst, src []byte) {
	decryptBlockC906(&c.decLE[0], c.rounds, &dst[0], &src[0], &c906Dec[0])
}

func checkGenericIsExpected() {}

// CTR32BlocksC906 is the counter mode of GCM for whole blocks: dst = src xor
// the key stream of len(src)/16 counter blocks, where the last four bytes of
// counter are a big-endian 32-bit counter that wraps and is advanced. dst
// and src have the same length, a positive multiple of the block size, and
// overlap entirely or not at all.
func CTR32BlocksC906(c *Block, dst, src []byte, counter *[BlockSize]byte) {
	ctr32BlocksC906(&c.encLE[0], c.rounds, &dst[0], &src[0], len(src)/BlockSize, counter, &c906Enc[0])
}
